# 1. Intentamos localizar la ruta real en el servidor web
rutas_posibles <- c(
  "/home/web_user/site/shinylive/packages",
  "/home/web_user/site/Prueba_RNA/shinylive/packages",
  "./shinylive/packages"
)

# Buscamos cual de las rutas existe realmente
ruta_final <- rutas_posibles[dir.exists(rutas_posibles)][1]

if(!is.na(ruta_final)) {
  .libPaths(c(ruta_final, .libPaths()))
}

library(shiny)

# 2. Carga forzada: si library() falla, usamos loadNamespace
tryCatch({
  library(RNASeqPower)
}, error = function(e) {
  if(!is.na(ruta_final)) {
    library(RNASeqPower, lib.loc = ruta_final)
  }
})

# --- UI y SERVER (Tu código base) ---
ui <- fluidPage(
  titlePanel("Calculadora RNA-Seq"),
  sidebarLayout(
    sidebarPanel(
      numericInput("depth", "Depth:", 100), 
      numericInput("cv", "CV:", 0.7), 
      numericInput("effect", "Effect:", 1.25), 
      numericInput("power", "Power:", 0.8), 
      numericInput("alpha", "Alpha:", 0.05),
      actionButton("btn_calcular", "CALCULAR")
    ),
    mainPanel(uiOutput("resultado"))
  )
)

server <- function(input, output) {
  calculo <- eventReactive(input$btn_calcular, {
    req(input$depth, input$cv, input$effect, input$alpha, input$power)
    # Usamos triple colon para forzar la entrada al paquete
    RNASeqPower:::rnapower(
      depth = input$depth, cv = input$cv, 
      effect = input$effect, alpha = input$alpha, 
      power = input$power
    )
  })
  output$resultado <- renderUI({
    if (input$btn_calcular == 0) return("Pulsa Calcular")
    h1(paste(ceiling(calculo()), "sujetos"))
  })
}

shinyApp(ui, server)
